import{_ as d,c as e,o as s,b0 as r,j as o,a}from"./chunks/framework.C5ev1SXp.js";const n="/scm-docs/assets/mcu-arch.D6HapMD4.svg",q=JSON.parse('{"title":"LV013-单片机的通用架构","description":null,"frontmatter":{"title":"LV013-单片机的通用架构","date":"2026-10-16T07:03:20.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/basic/computer-and-mcu/126d62aa68b005d840305a2c","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-10-16T07:03:20.093Z","fulluuid":"840305a2cb58475d899e21ad73ec9856","useduuid":"840305a2c"}},"headers":[],"relativePath":"sdoc/basic/computer-and-mcu/126d62aa68b005d840305a2c.md","filePath":"sdoc/10-基础篇/02-计算机与单片机基础/LV013-单片机的通用架构.md","lastUpdated":1792035518000}'),l={name:"sdoc/basic/computer-and-mcu/126d62aa68b005d840305a2c.md"},c={class:"MathJax",jax:"SVG",style:{direction:"ltr",position:"relative"}},i={style:{overflow:"visible","min-height":"1px","min-width":"1px","vertical-align":"0"},xmlns:"http://www.w3.org/2000/svg",width:"2.919ex",height:"1.887ex",role:"img",focusable:"false",viewBox:"0 -833.9 1290.1 833.9","aria-hidden":"true"};function u(h,t,p,m,g,b){return s(),e("div",null,[t[7]||(t[7]=r('<h1 id="lv013-单片机的通用架构" tabindex="-1">LV013-单片机的通用架构 <a class="header-anchor" href="#lv013-单片机的通用架构" aria-label="Permalink to &quot;LV013-单片机的通用架构&quot;">​</a></h1><p>前面几篇讲的都是&quot;计算机的通用原理&quot;和&quot;系统的组成&quot;，这一篇开始向芯片内部聚焦。先给出一个重要论断：<strong>所有单片机的内部架构都是同一个骨架</strong>——内核挂在总线上，总线上挂着存储器和各种外设。厂商不同、型号不同，变的只是各部件的规格和数量，骨架从 8 位机的 51 到 32 位机的 STM32 从未变过。</p><p>看懂这张通用的框图，你拿到任何一颗新 MCU 的数据手册都能迅速对号入座——只需要问三个问题：什么内核？多少存储？有哪些外设？</p><h2 id="一、-总览-一张通用框图" tabindex="-1">一、 总览：一张通用框图 <a class="header-anchor" href="#一、-总览-一张通用框图" aria-label="Permalink to &quot;一、 总览：一张通用框图&quot;">​</a></h2><p><img src="'+n+'" alt="通用单片机架构框图"></p><p>从下到上看这张图，分五个层次：</p><ul><li><strong>内核</strong>（CPU 子系统）：CPU 核心 + 内核外设（NVIC、SysTick），是芯片的大脑；</li><li><strong>高速总线 AHB</strong>：内核与存储器、支撑系统之间的骨干通道；</li><li><strong>存储器与支撑系统</strong>：FLASH、SRAM、时钟/复位挂在 AHB 上（电源管理等低速支撑电路挂在 APB 一侧）；</li><li><strong>外设总线 APB</strong>：经总线桥从 AHB 分出，挂载低速外设；</li><li><strong>片上外设</strong>：GPIO、定时器、串口等，面向控制对象的功能模块。</li></ul><p>芯片边界之外还有两样东西：外部晶振（给时钟系统提供节拍）和传感器/执行器（经引脚与片上外设相连）。下面自上而下逐层拆解。</p><h2 id="二、-内核-单片机的大脑" tabindex="-1">二、 内核：单片机的大脑 <a class="header-anchor" href="#二、-内核-单片机的大脑" aria-label="Permalink to &quot;二、 内核：单片机的大脑&quot;">​</a></h2><p>内核（Core）就是 <a href="/scm-docs/sdoc/basic/computer-and-mcu/126d62aa68ae1e86fc6cd55b.html">LV001</a> 里讲的 CPU 在单片机里的具体形态，包含三块。</p><h3 id="_1-处理器核心与指令集" tabindex="-1">1. 处理器核心与指令集 <a class="header-anchor" href="#_1-处理器核心与指令集" aria-label="Permalink to &quot;1. 处理器核心与指令集&quot;">​</a></h3><p>处理器核心包括寄存器组、ALU 和控制逻辑。定义&quot;这个 CPU 认识哪些指令&quot;的是<strong>指令集架构 ISA</strong>（Instruction Set Architecture）——目前 MCU 世界的主流是两大阵营：</p><p>（1）<strong>ARM Cortex-M</strong>：32 位 RISC 架构，ARM 公司设计内核、授权给芯片厂商（ST/NXP/GD/兆易等几十家）生产芯片。Cortex-M 家族又分档次：M0/M0+ 主打超低功耗低成本，M3 是性价比最平衡的一代（STM32F1 用它），M4 加了 DSP 指令和浮点单元，M7 主打高性能。<strong>内核统一是 Cortex-M 最大的生态优势</strong>：换厂商不用换知识；</p><p>（2）<strong>RISC-V</strong>：2010 年诞生的开源指令集，免授权费，模块化设计，是国产芯片（GD32V、CH32V、ESP32-C3）的新选择。</p><p>两大阵营的指令不兼容，但<strong>编程模型高度相似</strong>——寄存器、中断、异常、总线，学通一个另一个几天就能上手。</p><h3 id="_2-寄存器组" tabindex="-1">2. 寄存器组 <a class="header-anchor" href="#_2-寄存器组" aria-label="Permalink to &quot;2. 寄存器组&quot;">​</a></h3><p>内核里有一组速度极快的存储单元——寄存器（比任何存储器都快一个数量级），Cortex-M3 的寄存器组包括：</p><ul><li><strong>通用寄存器 R0～R12</strong>：放运算的操作数和结果；</li><li><strong>堆栈指针 SP</strong>（R13）：指向当前栈顶，函数调用、中断现场保存全靠它；</li><li><strong>链接寄存器 LR</strong>（R14）：保存函数返回地址；</li><li><strong>程序计数器 PC</strong>（R15）：指向下一条指令——就是 <a href="/scm-docs/sdoc/basic/computer-and-mcu/126d62aa68ae1e86fc6cd55b.html">LV001</a> 里那个驱动程序自动推进的 PC；</li><li><strong>程序状态寄存器 xPSR</strong>：记录标志位（零标志、进位、负数、溢出）和当前中断号。</li></ul><p>程序运行的本质就是&quot;在寄存器之间搬运和加工数据&quot;。Cortex-M 寄存器组的逐个详解见 <a href="/scm-docs/sdoc/basic/overview/126b08c73a222946645cba90.html">01-概述/LV030-CortexM3简介</a>。</p><h3 id="_3-内核外设-与大脑长在一起的部分" tabindex="-1">3. 内核外设：与大脑长在一起的部分 <a class="header-anchor" href="#_3-内核外设-与大脑长在一起的部分" aria-label="Permalink to &quot;3. 内核外设：与大脑长在一起的部分&quot;">​</a></h3><p>有些部件物理上和内核做在同一块区域、深度耦合，称为内核外设（区别于后面挂在总线上的片上外设）：</p><p>（1）<strong>NVIC</strong>（Nested Vectored Interrupt Controller，嵌套向量中断控制器）：管理所有中断的使能、优先级、嵌套与响应，是 Cortex-M 不可分割的一部分，详见 <a href="/scm-docs/sdoc/basic/overview/126b08e5d7b911b28ed9ee4c.html">01-概述/LV040-CortexM3异常</a> 与 <a href="/scm-docs/sdoc/basic/overview/126b08e5fb5429a0009ffc8b.html">LV045-CortexM3的NVIC中断控制</a>；</p><p>（2）<strong>SysTick</strong>：内核自带的 24 位向下计数定时器，为操作系统提供统一的&quot;心跳&quot;节拍（FreeRTOS 的 tick 就常用它）。</p><p>把它们做进内核的好处：所有用 Cortex-M 的芯片，中断行为和系统节拍的行为都完全一致，程序可移植性强。</p><h2 id="三、-总线与体系结构" tabindex="-1">三、 总线与体系结构 <a class="header-anchor" href="#三、-总线与体系结构" aria-label="Permalink to &quot;三、 总线与体系结构&quot;">​</a></h2><h3 id="_1-三类信号线" tabindex="-1">1. 三类信号线 <a class="header-anchor" href="#_1-三类信号线" aria-label="Permalink to &quot;1. 三类信号线&quot;">​</a></h3><p>总线（Bus）是连接各部件的一组公共信号线。<a href="/scm-docs/sdoc/basic/computer-and-mcu/126d62aa68ae1e86fc6cd55b.html">LV001</a> 讲过&quot;数据线&quot;和&quot;控制线&quot;，完整的总线其实有三类：</p>',27)),o("ul",null,[o("li",null,[t[2]||(t[2]=o("strong",null,"地址总线（AB，Address Bus）",-1)),t[3]||(t[3]=a("：单向，由内核发出，指明要访问哪个部件的哪个单元。位数决定寻址空间——32 位地址线可寻址 ",-1)),o("mjx-container",c,[(s(),e("svg",i,[...t[0]||(t[0]=[r('<g stroke="currentColor" fill="currentColor" stroke-width="0" transform="scale(1,-1)"><g data-mml-node="math"><g data-mml-node="msup"><g data-mml-node="mn"><path data-c="32" d="M109 429Q82 429 66 447T50 491Q50 562 103 614T235 666Q326 666 387 610T449 465Q449 422 429 383T381 315T301 241Q265 210 201 149L142 93L218 92Q375 92 385 97Q392 99 409 186V189H449V186Q448 183 436 95T421 3V0H50V19V31Q50 38 56 46T86 81Q115 113 136 137Q145 147 170 174T204 211T233 244T261 278T284 308T305 340T320 369T333 401T340 431T343 464Q343 527 309 573T212 619Q179 619 154 602T119 569T109 550Q109 549 114 549Q132 549 151 535T170 489Q170 464 154 447T109 429Z" style="stroke-width:3;"></path></g><g data-mml-node="TeXAtom" transform="translate(533,363) scale(0.707)" data-mjx-texclass="ORD"><g data-mml-node="mn"><path data-c="33" d="M127 463Q100 463 85 480T69 524Q69 579 117 622T233 665Q268 665 277 664Q351 652 390 611T430 522Q430 470 396 421T302 350L299 348Q299 347 308 345T337 336T375 315Q457 262 457 175Q457 96 395 37T238 -22Q158 -22 100 21T42 130Q42 158 60 175T105 193Q133 193 151 175T169 130Q169 119 166 110T159 94T148 82T136 74T126 70T118 67L114 66Q165 21 238 21Q293 21 321 74Q338 107 338 175V195Q338 290 274 322Q259 328 213 329L171 330L168 332Q166 335 166 348Q166 366 174 366Q202 366 232 371Q266 376 294 413T322 525V533Q322 590 287 612Q265 626 240 626Q208 626 181 615T143 592T132 580H135Q138 579 143 578T153 573T165 566T175 555T183 540T186 520Q186 498 172 481T127 463Z" style="stroke-width:3;"></path><path data-c="32" d="M109 429Q82 429 66 447T50 491Q50 562 103 614T235 666Q326 666 387 610T449 465Q449 422 429 383T381 315T301 241Q265 210 201 149L142 93L218 92Q375 92 385 97Q392 99 409 186V189H449V186Q448 183 436 95T421 3V0H50V19V31Q50 38 56 46T86 81Q115 113 136 137Q145 147 170 174T204 211T233 244T261 278T284 308T305 340T320 369T333 401T340 431T343 464Q343 527 309 573T212 619Q179 619 154 602T119 569T109 550Q109 549 114 549Q132 549 151 535T170 489Q170 464 154 447T109 429Z" transform="translate(500,0)" style="stroke-width:3;"></path></g></g></g></g></g>',1)])])),t[1]||(t[1]=o("mjx-assistive-mml",{unselectable:"on",display:"inline",style:{top:"0px",left:"0px",clip:"rect(1px, 1px, 1px, 1px)","-webkit-touch-callout":"none","-webkit-user-select":"none","-khtml-user-select":"none","-moz-user-select":"none","-ms-user-select":"none","user-select":"none",position:"absolute",padding:"1px 0px 0px 0px",border:"0px",display:"block",width:"auto",overflow:"hidden"}},[o("math",{xmlns:"http://www.w3.org/1998/Math/MathML"},[o("msup",null,[o("mn",null,"2"),o("mrow",{"data-mjx-texclass":"ORD"},[o("mn",null,"32")])])])],-1))]),t[4]||(t[4]=a(" = 4 GB；",-1))]),t[5]||(t[5]=o("li",null,[o("strong",null,"数据总线（DB，Data Bus）"),a("：双向，承载实际搬运的指令和数据，宽度常见 8/16/32 位；")],-1)),t[6]||(t[6]=o("li",null,[o("strong",null,"控制总线（CB，Control Bus）"),a("：混合方向，传递读写命令、时钟、中断请求、DMA 请求等协调信号。")],-1))]),t[8]||(t[8]=r('<p>所有部件都挂在同一组总线上，靠<strong>地址</strong>区分&quot;这次访问是谁&quot;——这就是后面&quot;存储器映射&quot;存在的前提。</p><h3 id="_2-分层总线-主干道与小马路" tabindex="-1">2. 分层总线：主干道与小马路 <a class="header-anchor" href="#_2-分层总线-主干道与小马路" aria-label="Permalink to &quot;2. 分层总线：主干道与小马路&quot;">​</a></h3><p>如果所有外设都挂在一条高速总线上，慢速外设（如 100 kHz 的 I2C）会拖累高速部件（如内核取指）。所以单片机的总线分成层级：</p><ul><li><strong>AHB</strong>（Advanced High-performance Bus）：高速骨干，内核、FLASH、SRAM、DMA、总线桥挂在上面，跑系统级高速率；</li><li><strong>APB</strong>（Advanced Peripheral Bus）：低速分支，经<strong>总线桥</strong>（Bridge）从 AHB 分出，GPIO、UART、定时器等低速外设挂在上面。</li></ul><p>像城市交通：先走主干道（AHB），到站后拐进小马路（APB）。慢速外设的访问不会阻塞主干道——既省成本（APB 逻辑简单），又不拖累关键路径。STM32F1 的具体总线结构（ICode/DCode/System 三条总线、BusMatrix 总线矩阵、APB1/APB2 两条分支）在 <a href="/scm-docs/sdoc/basic/stm32basic/126b08e6831f0a0031c3f015.html">10-STM32基础/LV040-STM32系统架构</a> 里详细拆解。</p><h3 id="_3-冯·诺依曼还是哈佛-单片机的选择" tabindex="-1">3. 冯·诺依曼还是哈佛：单片机的选择 <a class="header-anchor" href="#_3-冯·诺依曼还是哈佛-单片机的选择" aria-label="Permalink to &quot;3. 冯·诺依曼还是哈佛：单片机的选择&quot;">​</a></h3><p><a href="/scm-docs/sdoc/basic/computer-and-mcu/126d62aa68ae1e86fc6cd55b.html">LV001</a> 在介绍冯·诺依曼结构时，已经引出了它的&quot;对手&quot;哈佛结构（指令/数据分开存储、独立总线、并行访问），并给出了两种结构的总线级对比框图——建议先回看那一节。这里把差异收拢成一张速查表：</p><table tabindex="0"><thead><tr><th>维度</th><th>冯·诺依曼结构</th><th>哈佛结构</th></tr></thead><tbody><tr><td>程序与数据</td><td>同一存储器、同一组总线</td><td>分开存储、各有独立总线</td></tr><tr><td>取指与取数据</td><td>共用一条通道，只能轮流</td><td>两条通道，可以并行</td></tr><tr><td>存储分配</td><td>灵活，程序数据比例运行时可变</td><td>固定，程序区数据区出厂确定</td></tr><tr><td>结构与成本</td><td>简单、成本低</td><td>复杂、成本高</td></tr><tr><td>典型应用</td><td>早期计算机、PC 的统一内存</td><td>单片机（Cortex-M）、DSP</td></tr></tbody></table><p>结构选择的本质是一道取舍题：<strong>程序和数据要不要共用存储与访问通道</strong>。到这里，本篇已经讲完了单片机的存储介质（FLASH/SRAM 天然分工）和总线分层（AHB/APB），回答这道题所需的材料齐了——下一节正式展开。</p><h3 id="_4-单片机与-pc-各用什么架构" tabindex="-1">4. 单片机与 PC 各用什么架构 <a class="header-anchor" href="#_4-单片机与-pc-各用什么架构" aria-label="Permalink to &quot;4. 单片机与 PC 各用什么架构&quot;">​</a></h3><h4 id="_4-1-单片机-普遍采用哈佛结构" tabindex="-1">4.1 单片机：普遍采用哈佛结构 <a class="header-anchor" href="#_4-1-单片机-普遍采用哈佛结构" aria-label="Permalink to &quot;4.1 单片机：普遍采用哈佛结构&quot;">​</a></h4><p>主流单片机（包括 STM32 的 Cortex-M 内核）都采用哈佛结构，准确说是<strong>改进型哈佛结构</strong>。为什么单片机做了这个选择？四个原因，按分量排序：</p><p>（1）<strong>物理介质天然分开——这是&quot;必然&quot;而非&quot;选择&quot;</strong>。单片机的程序要求掉电不丢，只能放 FLASH；数据要求高速随机读写，只能放 SRAM。两种存储介质特性完全不同，物理上本来就是两块芯片区域——硬件形态天然就是哈佛结构，&quot;程序进 FLASH、数据进 SRAM&quot;只是顺应物理；</p><p>（2）<strong>性能：取指与取数并行</strong>。哈佛结构下 CPU 执行指令的同时可以预取下一条指令。Cortex-M 专门分出 I-Code（取指）和 D-Code（取数据）两条总线接入总线矩阵，再配合 FLASH 接口的预取缓冲，掩盖高主频下 FLASH 等待周期的影响（STM32F103 在 72 MHz 下就有 2 个等待周期），让程序尽量跑出标称性能；</p><p>（3）<strong>可靠性：程序区天然只读</strong>。控制类设备往往常年无人值守运行，&quot;程序被误改&quot;等于灾难。哈佛结构下指令存储器可以加硬件写保护，一个跑飞的野指针最多踩坏数据，改不动程序本身——配合看门狗复位就能恢复运行。这对 <a href="/scm-docs/sdoc/basic/computer-and-mcu/126d62aa68af2b7b388addac.html">LV010</a> 讲的&quot;最坏情况也可预期&quot;的可靠性哲学是重要一环；</p><p>（4）<strong>用不上统一内存的灵活性</strong>。PC 统一内存的核心红利是&quot;按需装载&quot;——但单片机的程序直接在 FLASH 里原地执行（XIP），上电即运行，根本没有&quot;把程序从磁盘搬进内存&quot;这一步；程序编译完就固化了，不存在运行中动态增减。灵活性的好处用不上，缺点的代价却要实付，自然不选冯·诺依曼。</p><p>再说<strong>改进型</strong>哈佛（Modified Harvard）的含义：纯粹的哈佛结构里，程序空间和数据空间连<strong>地址都不相通</strong>——早期 AVR 单片机就是这样，C 语言要用 <code>progmem</code> 关键字和两套指针分别访问 Flash 与 RAM 中的数据，非常别扭。Cortex-M 的改进是&quot;<strong>总线分开、地址统一</strong>&quot;：物理上取指总线和数据总线独立（保住并行的性能），逻辑上共享同一个 4 GB 统一地址空间（保住统一编址的编程便利——C 程序里一个指针可以按地址访问任何存储区，不用区分两套空间）。可以说 Cortex-M 同时拿到了两种结构的优点。</p><h4 id="_4-2-pc-冯·诺依曼式的统一内存" tabindex="-1">4.2 PC：冯·诺依曼式的统一内存 <a class="header-anchor" href="#_4-2-pc-冯·诺依曼式的统一内存" aria-label="Permalink to &quot;4.2 PC：冯·诺依曼式的统一内存&quot;">​</a></h4><p>PC 的主存是统一编址的 DRAM：操作系统内核、各个应用程序、它们的数据，全混放在同一个内存里，靠 MMU 划分区域互相隔离。整体上这是一台冯·诺依曼机器。为什么 PC 反着选？同样是需求决定的：</p><p>（1）<strong>灵活性是第一需求</strong>。PC 上程序是 GB 级的、数量不定——用户开多少个程序、每个程序处理多大的数据，事先全然不知。统一内存可以动态分配：程序大就多占，程序多就挤一挤。若用哈佛结构，程序区和数据区的大小出厂焊死，任何比例都会在某种负载下严重浪费；</p><p>（2）<strong>有磁盘和 MMU 支撑&quot;按需装载&quot;</strong>。程序平时躺在 SSD 里，运行时操作系统把它装进内存的任意空闲区域，MMU 的虚拟地址重定位让每个程序都&quot;以为&quot;自己独占内存（详见 <a href="/scm-docs/sdoc/basic/computer-and-mcu/126d62aa68af2b7b388addac.html">LV010</a> 关于 MMU 的展开）。这套机制以统一内存为前提——程序可以被装到任何地址，恰恰因为内存不分&quot;谁的区&quot;；</p><p>（3）<strong>多任务共享内存</strong>。几十个进程共用一套 DRAM、按需增减、靠 MMU 隔离，这是现代操作系统的地基。两套物理分开的存储器会让进程管理、内存回收的复杂度爆炸；</p><p>（4）<strong>成本</strong>。一套大容量通用 DRAM 比两套各占一半的专用存储便宜得多，产业生态也统一；</p><p>（5）<strong>性能短板用缓存补</strong>。冯·诺依曼瓶颈的解法不是改主存结构，而是在 CPU 近旁加多级 Cache：频繁访问的指令和数据被缓存到离内核最近的地方。有意思的是，<strong>现代 x86 CPU 的 L1 缓存恰恰是指令、数据分开的</strong>（L1i 与 L1d）——离内核最近的存储层偷偷&quot;哈佛化&quot;了，主存层保持冯·诺依曼。</p><p>【<strong>注意</strong>】</p><p>两种结构的边界比教科书印象更模糊：单片机在物理哈佛之上做了统一编址（吸收冯·诺依曼的编程便利），PC 在统一内存之上做了分缓存（吸收哈佛的并行性能）。工程世界里没有结构教条，只有&quot;为设计目标取舍&quot;——<strong>单片机&quot;程序固化、数据量小、求稳求快&quot;，所以哈佛；PC&quot;程序海量、动态装载、求灵活&quot;，所以冯·诺依曼</strong>。</p><h2 id="四、-存储器-flash-与-sram" tabindex="-1">四、 存储器：FLASH 与 SRAM <a class="header-anchor" href="#四、-存储器-flash-与-sram" aria-label="Permalink to &quot;四、 存储器：FLASH 与 SRAM&quot;">​</a></h2><h3 id="_1-分工" tabindex="-1">1. 分工 <a class="header-anchor" href="#_1-分工" aria-label="Permalink to &quot;1. 分工&quot;">​</a></h3><p><a href="/scm-docs/sdoc/basic/computer-and-mcu/126d62aa68af11d1e75dc1b7.html">LV007</a> 说过单片机把主存拆成两块，这里给出完整对比：</p><table tabindex="0"><thead><tr><th>维度</th><th>FLASH（闪存）</th><th>SRAM（静态随机存储器）</th></tr></thead><tbody><tr><td>存什么</td><td>编译好的程序、常量、中断向量表</td><td>变量、堆栈、动态数据</td></tr><tr><td>掉电后</td><td>数据保留（非易失）</td><td>数据丢失（易失）</td></tr><tr><td>读写特点</td><td>随机读快；写之前必须按扇区擦除，寿命有限（万次级）</td><td>随机读写极快，无限次</td></tr><tr><td>成本与密度</td><td>便宜、密度高</td><td>贵、密度低</td></tr><tr><td>STM32F103C8T6</td><td>64 KB</td><td>20 KB</td></tr></tbody></table><p>为什么不给 SRAM 也做成掉电不丢？成本和工艺不允许；为什么不用 FLASH 跑变量？擦写太慢且寿命有限。两者分工是物理特性决定的必然。</p><h3 id="_2-xip-代码原地执行" tabindex="-1">2. XIP：代码原地执行 <a class="header-anchor" href="#_2-xip-代码原地执行" aria-label="Permalink to &quot;2. XIP：代码原地执行&quot;">​</a></h3><p>CPU 直接从 FLASH 取指执行，不需要先把程序搬到 RAM——这叫 <strong>XIP</strong>（eXecute In Place，片内执行/原地执行）。它依赖 FLASH 的<strong>字节级随机读</strong>能力：CPU 给一个地址，FLASH 立刻返回该地址的数据，满足取指时序要求。这也是单片机选 NOR FLASH 存程序的原因（NAND 只能按块读，CPU 没法直接取指）——详见 <a href="/scm-docs/sdoc/basic/overview/126b08ba13b3329986816cf4.html">01-概述/LV010-常见存储器</a> 与 <a href="/scm-docs/sdoc/basic/overview/126b087fdd56e1ad943bdccc.html">LV012-EEPROM与Flash</a>。</p><p>一个例外值得知道：当需要&quot;运行中自我更新程序&quot;（IAP/Bootloader）时，MCU 不能一边从 FLASH 取指一边擦写同一片 FLASH——这时要把一小段代码搬进 SRAM 执行，见 <a href="/scm-docs/sdoc/basic/stm32setup/126b08e7afad049a561ccf1b.html">20-STM32的启动/LV010-在内部SRAM调试</a>。</p><h3 id="_3-统一地址空间与存储器映射" tabindex="-1">3. 统一地址空间与存储器映射 <a class="header-anchor" href="#_3-统一地址空间与存储器映射" aria-label="Permalink to &quot;3. 统一地址空间与存储器映射&quot;">​</a></h3><p>FLASH、SRAM、每个外设，全部被编进同一个 4 GB 地址空间——<strong>一张&quot;地址 → 部件&quot;的对照表管理整颗芯片</strong>，这张表就是存储器映射（Memory Map）。访问 0x2000 0000 就是访问 SRAM，访问 0x4001 0800 就是访问 GPIOA 的寄存器。&quot;地址即部件&quot;是理解单片机编程的关键一跃，完整机制留到 <a href="/scm-docs/sdoc/basic/computer-and-mcu/126d62aa68b01ec0b1738d7e.html">LV016-寄存器与硬件控制</a> 展开，Cortex-M 的空间划分见 <a href="/scm-docs/sdoc/basic/overview/126b08e6a7051c291c1151a6.html">01-概述/LV022-CortexM0存储器映射</a> 与 <a href="/scm-docs/sdoc/basic/overview/126b08c73d361161792b640a.html">01-概述/LV035-CortexM3存储器系统</a>。</p><h2 id="五、-片上外设-单片机的手脚" tabindex="-1">五、 片上外设：单片机的手脚 <a class="header-anchor" href="#五、-片上外设-单片机的手脚" aria-label="Permalink to &quot;五、 片上外设：单片机的手脚&quot;">​</a></h2><p>外设（Peripheral）是集成在芯片内、面向控制对象的功能模块。按功能分四类：</p><ul><li><strong>数字 I/O 类</strong>：<strong>GPIO</strong>——最基本的外设，每个引脚可配成输入或输出，读按键、点灯、模拟时序全靠它，是&quot;单片机的手&quot;；</li><li><strong>通信类</strong>：<strong>UART</strong>（串口，最经典的调试通道）、<strong>I2C/SPI</strong>（连接传感器和存储芯片）、<strong>CAN</strong>（汽车与工业现场）、<strong>USB</strong>——是&quot;单片机的嘴和耳朵&quot;；</li><li><strong>模拟类</strong>：<strong>ADC</strong>（模数转换，把电压变成数字）、<strong>DAC</strong>（数模转换）——连接模拟世界的桥梁；</li><li><strong>定时控制类</strong>：<strong>定时器 TIM</strong>（定时、计数、PWM 输出、输入捕获）、<strong>看门狗 IWDG/WWDG</strong>（程序跑飞时复位自救）、<strong>RTC</strong>（实时时钟）；</li><li><strong>数据搬运类</strong>：<strong>DMA</strong>（不经 CPU 在存储器与外设之间搬运数据，给内核减负）。</li></ul><p>外设不直接连在内核上，而是挂在总线上，每个外设有自己的寄存器组；内核通过读写这些寄存器来指挥外设——这正是 <a href="/scm-docs/sdoc/basic/computer-and-mcu/126d62aa68b01ec0b1738d7e.html">LV016</a> 的主题。本站《基本外设篇》将逐个深入。</p><h2 id="六、-支撑系统-让芯片活着" tabindex="-1">六、 支撑系统：让芯片活着 <a class="header-anchor" href="#六、-支撑系统-让芯片活着" aria-label="Permalink to &quot;六、 支撑系统：让芯片活着&quot;">​</a></h2><p>框图外围还有三组不起眼但缺一不可的电路，它们不参与计算，却决定芯片能否工作：</p><p>（1）<strong>时钟系统</strong>：单片机每个动作都按节拍进行。外部晶振（HSE）或内部振荡器（HSI）经 PLL 倍频产生主时钟 SYSCLK，再经 AHB/APB 分频分给 CPU 和各外设——这棵&quot;时钟树&quot;决定每个部件跑多快，也决定了功耗大小（给不用的外设关时钟是省电的基本功）。详见 <a href="/scm-docs/sdoc/basic/stm32clock/126b08f5d89727a6ee395582.html">40-STM32时钟/LV001-STM32F1时钟系统</a>；</p><p>（2）<strong>复位与电源</strong>：上电复位、手动复位、看门狗复位、欠压复位；电源管理提供睡眠/停止/待机等低功耗模式，是电池类产品的命根子；</p><p>（3）<strong>调试接口</strong>：SWD/JTAG，PC 通过它烧写程序、单步调试、观察变量——没有它就没有嵌入式开发效率。</p><h2 id="七、-拿-stm32f103-对号入座" tabindex="-1">七、 拿 STM32F103 对号入座 <a class="header-anchor" href="#七、-拿-stm32f103-对号入座" aria-label="Permalink to &quot;七、 拿 STM32F103 对号入座&quot;">​</a></h2><p>把通用骨架套到 STM32F103 上逐项验证：</p><table tabindex="0"><thead><tr><th>通用骨架的部件</th><th>STM32F103（以 C8T6 为例）</th></tr></thead><tbody><tr><td>内核</td><td>Cortex-M3，72 MHz，512 KB 以下 FLASH 型号的主流选择</td></tr><tr><td>指令集</td><td>ARMv7-M（Thumb-2）</td></tr><tr><td>FLASH / SRAM</td><td>64 KB / 20 KB</td></tr><tr><td>高速总线</td><td>AHB + BusMatrix（ICode/DCode/System 三条接口）</td></tr><tr><td>外设总线</td><td>APB1（36 MHz）/ APB2（72 MHz）两条</td></tr><tr><td>片上外设</td><td>2×SPI、2×I2C、3×USART、1×USB、1×CAN、2×ADC、4×定时器、37 个 GPIO</td></tr><tr><td>支撑系统</td><td>HSE 8 MHz 晶振 + PLL ×9 = 72 MHz，SWD 调试</td></tr></tbody></table><p>展开版的详细框图见 <a href="/scm-docs/sdoc/basic/stm32basic/126b08e6831f0a0031c3f015.html">10-STM32基础/LV040-STM32系统架构</a>。</p><p><strong>记住这张骨架图的价值</strong>：以后看任何一颗新 MCU——不管厂商吹得多天花乱坠——都是&quot;内核 + 总线 + 存储 + 外设&quot;的排列组合。对着数据手册问三个问题（什么内核？多少存储？有哪些外设？），芯片的定位和选型方向就基本清楚了。骨架之外还有两个藏在内核里的问题：CPU 认识哪些指令（指令集）？它靠什么把指令执行得又快又稳（流水线）？这就是下一篇 <a href="/scm-docs/sdoc/basic/computer-and-mcu/126d62aa93073c6745351be7.html">LV014-指令集与流水线</a> 的内容。</p><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>',52))])}const M=d(l,[["render",u]]);export{q as __pageData,M as default};
